'use strict';

// ════════════════════════════════════════════════════════════════════════════
// VIDEO -> GENERATED BY THE MODEL THAT MADE IT.
//
// Every B-roll lies in the FOLDER OF ITS MODEL - a B-roll category at the top whose id is `model_<model>` (lib/library-cats.js
// isModelId: the app's, locked - never renamed, moved or deleted), named as the video chat names the model (lib/video-models.js
// label; P-Video and Other besides) - directly, or in a group (a folder of the person's) inside it, at any depth: on the disk
// media/birols/<model>/<group>/... The media tree shows them in VIDEO -> Generated (routes/library.js _tree); a model's folder
// only while something lies under it (an emptied one is gone from the tree - its record and its groups stay, and it is
// back with its next clip). A clip of one model never goes into another's folder (refused in words - targetFor), nor
// a folder with them (moveWhy). The video chat's clip lies in its model's folder itself (lib/birols-store.js add).
//
// What made a clip: the folder it lies under (its model's); else the record's meta.model (the video chat's); else the clip it
// was cut from (`original`); else - older clips kept no model, but their FILE NAMES say it - grok_ /
// grok_txt_ are Grok classic (grok-imagine on kie, xai/grok-imagine-video on Replicate, never Grok 1.5), pvid_ P-Video;
// else Other. The names are asked only of older clips (the sweep, a clip made a B-roll again): a file brought in now
// proves nothing by its name.
//
//   isModelCat(id), modelOfCat(state, id), labelOf(model), folderFor(model) -> the category (made when missing)
//   modelOf(rec, { state, list, byName }), targetFor(rec, catId, opts) -> { id, label } | throws (409) in words
//   groupFor(model, label) -> a group of that name in the model's folder (made when missing)
//   moveWhy(state, id, parent) -> why that folder cannot go there, or ''
//   sweep({ log }) -> what was done | null   when the server starts (routes/library.js): the first time it puts the library
//                    into the models' folders - the stores copied into backups/ first; after that, a clip that came to lie
//                    outside them goes into its model's folder. A library that is in order is left alone.
// ════════════════════════════════════════════════════════════════════════════

const fs = require('fs');
const path = require('path');
const LC = require('./library-cats');
const { ROOT_DIR } = require('./config');
const I18N = require('./i18n');

const KIND = 'birols';
const OTHER = 'other';
const LABELS = { pvideo: 'P-Video', other: 'Other' };
const VM = () => require('./video-models');
const _lc = (s) => String(s || '').trim().toLowerCase();

const isModelCat = (id) => LC.isModelId(id);
const folderId = (model) => LC.MODEL_PREFIX + model;
const _modelIdOf = (catId) => String(catId).slice(LC.MODEL_PREFIX.length);
// A model id as a folder's id takes it: letters and digits.
const _clean = (m) => (/^[a-z0-9]{1,30}$/.test(String(m || '')) ? String(m) : '');
const _isB = (e) => !!(e && e.videoPath && e.source !== 'upload');
const B = () => require('./birols-store');

/** A model's name, as the video chat says it - "Grok classic", "Seedance 2.5"; P-Video, Other. */
function labelOf(model) {
  if (LABELS[model]) return LABELS[model];
  try { const l = VM().label(model); if (l) return String(l); } catch (e) { /* the list unread: its id */ }
  return String(model || 'Other');
}

/** The model whose folder `catId` lies in (the folder itself too) - '' when none: no folder, or one outside every model's. */
function modelOfCat(state, catId) {
  const st = state || LC.read();
  let top = null;
  for (let c = LC.byIdOf(st, KIND, catId); c; c = LC.byIdOf(st, KIND, c.parent)) top = c;
  return top && isModelCat(top.id) ? _modelIdOf(top.id) : '';
}

// Older clips: the model by the file's name.
function _byName(url) {
  const n = path.posix.basename(String(url || '').split(/[?#]/)[0]);
  if (/^grok_/i.test(n)) return 'grok';
  if (/^pvid_/i.test(n)) return 'pvideo';
  return '';
}

// A piece's: the model of the clip it was cut from (lib/cuts.js `original`), when that clip is a B-roll of the shelf.
function _fromOriginal(rec, st, list, byName) {
  const o = rec && rec.original;
  if (!o || !o.path) return '';
  const want = String(o.path).split('?')[0];
  const src = (list || B().read()).find(e => _isB(e) && String(e.videoPath || '').split('?')[0] === want);
  if (!src) return byName ? _byName(want) : '';
  return modelOfCat(st, src.categoryId) || _clean(src.meta && src.meta.model) || (byName ? _byName(src.videoPath) : '');
}

/** What made this B-roll (see the head of this file); `byName` - ask the file's name too (older clips). */
function modelOf(rec, opts) {
  const o = opts || {};
  const st = o.state || LC.read();
  return modelOfCat(st, rec && rec.categoryId)
    || _clean(rec && rec.meta && rec.meta.model)
    || _fromOriginal(rec, st, o.list, !!o.byName)
    || (o.byName ? _byName(rec && rec.videoPath) : '')
    || OTHER;
}

/** The folder of a model - made, at the top of B-rolls under the model's name, when it is not there yet. */
function folderFor(model) {
  const m = _clean(model) || OTHER;
  const id = folderId(m);
  const have = LC.byIdOf(LC.read(), KIND, id);
  if (have) return have;
  return LC.adopt(KIND, id, labelOf(m));
}

/** A group of that name in a model's folder - the one there (directly in it first, then anywhere under it), or a new one. */
function groupFor(model, label) {
  const f = folderFor(model);
  const name = String(label || '').trim().slice(0, 60);
  if (!name) return f;
  const state = LC.read();
  const under = LC.subtreeOf(state, KIND, f.id).slice(1).map(id => LC.byIdOf(state, KIND, id)).filter(Boolean);
  const hit = under.find(c => c.parent === f.id && _lc(c.label) === _lc(name)) || under.find(c => _lc(c.label) === _lc(name));
  return hit || LC.make(KIND, name, f.id).cat;
}

// A model's folder as a person reads it: Other in the interface's language (its stored name stays), a model by its name.
const _said = (model) => (model === OTHER ? I18N.t('Other') : labelOf(model));

// Why a clip of `model` does not go into a folder of `there`'s, in words.
function _stays(model, there) {
  return model === OTHER
    ? I18N.t('What made this clip is not known - it stays in Other, not in {there}.', { there: _said(there) })
    : I18N.t('Made by {model} - it stays in {model}, not in {there}.', { model: _said(model), there: _said(there) });
}

/**
 * Where a B-roll filed into `catId` lies: '' (or Uncategorized) - the root of its model's folder; a folder in its model's
 * folder - that one; a folder in another model's - refused (409, in words). A folder outside every model's (a library not
 * yet swept) is taken as it is: the sweep puts it in its place. -> { id, label }
 */
function targetFor(rec, catId, opts) {
  const state = LC.read();
  // `opts.model` - a record being filed carries the folder asked for already: what made it is said, not read from that.
  const model = (opts && opts.model) || modelOf(rec, Object.assign({ state }, opts || {}));
  const want = String(catId || '');
  if (!want || want === LC.UNCAT) { const f = folderFor(model); return { id: f.id, label: f.label }; }
  const there = modelOfCat(state, want);
  if (there && there !== model) throw Object.assign(new Error(_stays(model, there)), { status: 409 });
  const c = LC.byIdOf(state, KIND, want);
  return { id: want, label: c ? c.label : '' };
}

/** Why the B-roll folder `id` cannot go into `parent` ('' - the top), in words - '' when it may. */
function moveWhy(state, id, parent) {
  const st = state || LC.read();
  if (!parent) return LC.modelsTop();
  const from = modelOfCat(st, id);
  const to = modelOfCat(st, parent);
  if (from && to !== from) {
    const c = LC.byIdOf(st, KIND, id);
    return I18N.t('The clips in "{name}" were made by {model} - the folder stays in {model}.',
      { name: (c && c.label) || I18N.t('this folder'), model: _said(from) });
  }
  return '';
}

/** The folder that holds what a B-roll folder holds when it is emptied into "the kind itself": its model's. */
function rootOf(state, id) {
  const m = modelOfCat(state || LC.read(), id);
  return m ? folderId(m) : '';
}

// ── The sweep, when the server starts ──────────────────────────────────────
// Every store a moved address can be in (lib/relocate.js storeFiles) that names a B-roll's file, and the two lists themselves,
// copied as they are into backups/<day> by model/ - before anything moves.
function _backup(log) {
  const now = new Date();
  const day = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  let rel = `backups/${day} by model`;
  for (let i = 2; fs.existsSync(path.join(ROOT_DIR, rel)); i++) rel = `backups/${day} by model (${i})`;
  const at = path.join(ROOT_DIR, rel);
  fs.mkdirSync(at, { recursive: true });
  let n = 0;
  for (const abs of require('./relocate').storeFiles()) {
    let raw = '';
    try { raw = fs.readFileSync(abs, 'utf8'); } catch (e) { continue; }
    const base = path.basename(abs);
    if (!raw.includes('/media/birols/') && base !== 'library-cats.json' && base !== 'biroly.json') continue;
    const to = path.join(at, path.relative(ROOT_DIR, abs));
    fs.mkdirSync(path.dirname(to), { recursive: true });
    fs.copyFileSync(abs, to);
    n++;
  }
  fs.writeFileSync(path.join(at, 'README.txt'), [
    'VIDEO -> Generated by model: the B-rolls went into the folders of the models that made them -',
    'media/birols/<model>/<group>/ - and every store and timeline that named their files was rewritten.',
    'These are those stores as they were before (paths relative to the library). To go back, close the app, put these',
    'files back and move media/birols/<model>/<group>/ back to media/birols/<group>/ (and the clips with no group back',
    'into media/birols/nocat/).', ''].join('\r\n'));
  log('[models] the stores as they were (' + n + ' files) are in ' + rel);
  return rel;
}

// The folder of the same path as `catId` (from its top folder down) in a model's folder - made where missing.
function _mirror(catId, model) {
  const st = LC.read();
  const chain = [];
  for (let c = LC.byIdOf(st, KIND, catId); c; c = LC.byIdOf(st, KIND, c.parent)) chain.unshift(c.label);
  let at = folderFor(model);
  for (const label of chain) {
    const now = LC.read();
    const have = LC.kidsOf(now, KIND, at.id).find(c => _lc(c.label) === _lc(label));
    at = have || LC.make(KIND, label, at.id).cat;
  }
  return at;
}

// The records of `ids` given these categories (`to`: id -> category), written, and their files placed - one relocate.
function _refile(to) {
  if (!to.size) return 0;
  const list = B().read();
  const placed = [];
  for (const e of list) {
    const c = e && to.get(String(e.id));
    if (!c) continue;
    e.categoryId = c.id;
    e.categoryLabel = c.label;
    placed.push(String(e.id));
  }
  if (!placed.length) return 0;
  B().write(list);
  const ids = new Set(placed);
  require('./shelf-files').placeRecords(B().read().filter(e => e && ids.has(String(e.id))).map(rec => ({ kind: KIND, rec })));
  return placed.length;
}

function sweep(opts) {
  const log = (opts && opts.log) || ((s) => console.log(s));
  const F = require('./folders');
  let state = LC.read();
  const all = B().read();
  const recs = all.filter(_isB);
  const strays = LC.kidsOf(state, KIND, '').filter(c => !isModelCat(c.id));
  const loose0 = recs.filter(e => !modelOfCat(state, e.categoryId));
  if (!strays.length && !loose0.length) return null;

  const out = { backup: _backup(log), groups: [], split: 0, loose: 0, models: {} };
  // What made each clip, asked once - before anything moves (a piece's source may move first).
  const made = new Map(recs.map(e => [String(e.id), modelOf(e, { state, list: all, byName: true })]));
  const tally = (list) => {
    const t = {};
    for (const e of list) { const m = made.get(String(e.id)) || OTHER; t[m] = (t[m] || 0) + 1; }
    return t;
  };
  const most = (t) => Object.entries(t).sort((a, b) => b[1] - a[1] || (a[0] === OTHER) - (b[0] === OTHER) || a[0].localeCompare(b[0]))[0];
  const overall = most(tally(recs));

  // A group outside every model's (an older library keeps its groups at the top): into the folder of the model that
  // made most of its clips, with every folder under it - one relocate; its clips of other models first into a group of the
  // same name in theirs ("girls" in Grok classic and "girls" in Kling 2.6 motion control). A group with nothing in
  // it goes with most of the library's clips.
  for (const g of strays) {
    state = LC.read();
    if (!LC.byIdOf(state, KIND, g.id)) continue;
    const sub = new Set(LC.subtreeOf(state, KIND, g.id));
    const inG = B().read().filter(e => _isB(e) && sub.has(String(e.categoryId || '')));
    const top = most(tally(inG)) || overall;
    const main = top ? top[0] : OTHER;
    const others = new Map();
    for (const e of inG) {
      const m = made.get(String(e.id)) || OTHER;
      if (m !== main) others.set(String(e.id), _mirror(e.categoryId, m));
    }
    const split = _refile(others);
    out.split += split;
    const into = folderFor(main);
    // A name its model's folder has already (a group of the same name split there before): "Name (2)", the app's way.
    state = LC.read();
    const here = LC.byIdOf(state, KIND, g.id);
    if (LC.siblingNamed(state, KIND, into.id, here.label, here.id)) {
      const taken = new Set(LC.kidsOf(state, KIND, into.id).map(c => _lc(c.label)));
      let label = here.label;
      for (let n = 2; taken.has(_lc(label)); n++) label = here.label.slice(0, 55) + ' (' + n + ')';
      F.rename(KIND, g.id, label);
    }
    F.move(KIND, g.id, into.id);
    out.groups.push(here.label + ' -> ' + into.label + ' (' + (inG.length - split) + (split ? ', ' + split + ' to their own models' : '') + ')');
  }

  // The clips that lie in no group (media/birols/nocat/), or in a folder no list knows: into their model's folder itself.
  state = LC.read();
  const loose = new Map();
  for (const e of B().read().filter(_isB)) {
    if (modelOfCat(state, e.categoryId)) continue;
    const f = folderFor(made.get(String(e.id)) || modelOf(e, { byName: true }));
    loose.set(String(e.id), { id: f.id, label: f.label });
  }
  out.loose = _refile(loose);

  state = LC.read();
  for (const e of B().read().filter(_isB)) {
    const m = modelOfCat(state, e.categoryId) || '?';
    out.models[labelOf(m)] = (out.models[labelOf(m)] || 0) + 1;
  }
  log('[models] B-rolls into the folders of the models that made them: ' + out.groups.length + ' group(s) moved'
    + (out.split ? ', ' + out.split + ' clip(s) of another model into a group of the same name in theirs' : '')
    + (out.loose ? ', ' + out.loose + ' clip(s) with no group into their model\'s folder' : '')
    + ' - now ' + Object.entries(out.models).map(([k, n]) => k + ' ' + n).join(', '));
  for (const g of out.groups) log('[models]   ' + g);
  return out;
}

module.exports = { KIND, OTHER, isModelCat, folderId, labelOf, modelOfCat, modelOf, folderFor, groupFor, targetFor, moveWhy, rootOf, sweep };
